contracts/AgentGate.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IAgentID} from "./IAgentID.sol";

/// @title AgentGate — reusable Agent ID gate for BNB Smart Chain projects
/// @notice Inherit from this contract to restrict any function to holders of
///         a SPACE ID Agent ID (0x60b9262456de011f7d15a54cdd8c48baaa8b022f on
///         BSC). An Agent ID is a non-transferable, one-per-verified-person
///         ERC-721 identity (`name.ai`), so gating on it gives a project
///         Sybil resistance that a plain address allowlist cannot: one human
///         can pass the gate exactly once, no matter how many wallets they
///         create.
///
/// @dev Integration is deliberately boring:
///
///      ```solidity
///      contract MyDrop is AgentGate {
///          constructor() AgentGate(0x60b9262456de011f7d15a54cdd8c48baaa8b022f) {}
///
///          function mint() external {
///              _requireAgentID();          // reverts unless caller holds an Agent ID
///              // ... your logic ...
///          }
///      }
///      ```
///
///      Design notes:
///      - The Agent ID contract address is `immutable`: it is fixed at
///        deployment, can never be swapped for a weaker identity contract,
///        and costs no storage read on the hot path.
///      - The gate is a *check*, not a registry: AgentGate stores nothing
///        about holders. Per-person claim tracking (one mint per ID, ever)
///        is the inheriting contract's job — see AgentGateBadge for the
///        reference implementation.
///      - The gate fails closed: if the identity contract call reverts or
///        returns 0, access is denied.
abstract contract AgentGate {
    /// @notice The Agent ID (SPACE ID) contract this gate checks against.
    /// @dev Immutable by design — see the contract-level notes above.
    IAgentID public immutable agentID;

    /// @notice Emitted never by the base contract itself; declared here so
    ///         integrators share one canonical event shape when they record
    ///         a gate pass. See AgentGateBadge for usage.
    event AgentIDVerified(address indexed holder);

    /// @notice The caller (or checked address) does not hold an Agent ID.
    error NoAgentID(address account);

    /// @param agentIDAddress Address of the Agent ID contract on this chain.
    ///        On BSC mainnet: 0x60b9262456de011f7d15a54cdd8c48baaa8b022f.
    constructor(address agentIDAddress) {
        require(agentIDAddress != address(0), "AgentGate: zero address");
        agentID = IAgentID(agentIDAddress);
    }

    /// @notice Does `account` hold an Agent ID?
    /// @param account The address to check.
    /// @return True if the address holds at least one Agent ID.
    function hasAgentID(address account) public view returns (bool) {
        return agentID.balanceOf(account) > 0;
    }

    /// @notice Revert unless `msg.sender` holds an Agent ID.
    /// @dev The one line an integrator needs. Fails closed with a typed
    ///      error carrying the offending address for easy debugging.
    function _requireAgentID() internal view {
        if (!hasAgentID(msg.sender)) {
            revert NoAgentID(msg.sender);
        }
    }

    /// @notice Revert unless `account` holds an Agent ID.
    /// @param account The address to check (e.g. a recipient distinct from
    ///        the caller).
    function _requireAgentIDOf(address account) internal view {
        if (!hasAgentID(account)) {
            revert NoAgentID(account);
        }
    }
}

contracts/AgentGateBadge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AgentGate} from "./AgentGate.sol";
import {ERC721Minimal, OwnableMinimal} from "./ERC721Minimal.sol";

/// @title AgentGateBadge — free commemorative badge, mintable only by Agent ID holders
/// @notice The reference product built on AgentGate. `mint()` is FREE (the
///         contract holds no funds and has no payable functions at all) and
///         is gated by the caller's Agent ID: because an Agent ID is
///         one-per-verified-person and non-transferable, "one badge per
///         address, ever" is in practice "one badge per human, ever" —
///         minting a second badge from a fresh wallet does not work,
///         because the fresh wallet holds no Agent ID.
///
/// @dev Owner powers — the COMPLETE list (also disclosed in README.md):
///        1. `setMintOpen(bool)` — open or close the mint window.
///        2. `setMaxSupply(uint256)` — LOWER the supply cap only. The cap
///           can never be raised, and never set below the amount already
///           minted. (Restrictive by design: nobody — not even the owner —
///           can dilute the badge after the fact.)
///        3. `transferOwnership` / `renounceOwnership` — hand over or give
///           up the two powers above. Renouncing freezes the window and
///           cap forever.
///      The owner CANNOT: mint (the owner must pass the same Agent ID gate
///      as everyone else, via the public `mint()`), block or reverse
///      transfers, charge fees, pause anything else, or withdraw funds
///      (the contract cannot receive funds in the first place).
contract AgentGateBadge is AgentGate, ERC721Minimal, OwnableMinimal {
    /// @notice The one metadata document describing every badge in this
    ///         collection. Fixed at construction; there is no setter.
    string public metadataURI;

    /// @notice Hard cap on badges that can ever exist. Can only go down
    ///         (see `setMaxSupply`), never up.
    uint256 public maxSupply;

    /// @notice How many badges have been minted so far. Token ids run
    ///         1..totalMinted.
    uint256 public totalMinted;

    /// @notice Whether the mint window is currently open. Starts CLOSED;
    ///         the owner opens it explicitly after deployment.
    bool public mintOpen;

    /// @notice Per-address claim record: true once an address has minted.
    ///         Together with the Agent ID gate this enforces one badge per
    ///         person, permanently — the mapping is never reset.
    mapping(address => bool) public claimed;

    event BadgeMinted(address indexed holder, uint256 indexed tokenId);
    event MintWindowChanged(bool open);
    event MaxSupplyChanged(uint256 oldMaxSupply, uint256 newMaxSupply);

    error MintClosed();
    error AlreadyClaimed(address account);
    error SoldOut();
    error InvalidMaxSupply(uint256 newMaxSupply);

    /// @param agentIDAddress The Agent ID contract (BSC mainnet:
    ///        0x60b9262456de011f7d15a54cdd8c48baaa8b022f).
    /// @param metadataURI_ Fixed metadata URI returned by `tokenURI` for
    ///        every badge (an IPFS or HTTPS JSON document).
    /// @param maxSupply_ Initial supply cap. 10,000 for the live deployment.
    constructor(
        address agentIDAddress,
        string memory metadataURI_,
        uint256 maxSupply_
    ) AgentGate(agentIDAddress) ERC721Minimal("AgentGate Badge", "AGB") {
        require(maxSupply_ > 0, "Badge: zero supply");
        metadataURI = metadataURI_;
        maxSupply = maxSupply_;
        mintOpen = false;
    }

    /// @notice Mint your badge. Free. One per Agent ID holder, ever.
    /// @dev Check order is deliberate: window → claim record → supply →
    ///      identity. The identity check (`_requireAgentID`) is last so
    ///      the cheap local reverts fire first, but no path reaches the
    ///      mint without passing it.
    function mint() external {
        if (!mintOpen) revert MintClosed();
        if (claimed[msg.sender]) revert AlreadyClaimed(msg.sender);
        if (totalMinted >= maxSupply) revert SoldOut();

        // The centerpiece: only an Agent ID holder gets through this line.
        _requireAgentID();

        claimed[msg.sender] = true;
        uint256 tokenId = ++totalMinted;
        emit AgentIDVerified(msg.sender);
        emit BadgeMinted(msg.sender, tokenId);
        _safeMint(msg.sender, tokenId);
    }

    /// @notice Has `account` already claimed its badge?
    function hasClaimed(address account) external view returns (bool) {
        return claimed[account];
    }

    /// @notice The fixed collection metadata URI (identical for every
    ///         token; reverts for tokens that do not exist).
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(tokenId >= 1 && tokenId <= totalMinted, "Badge: nonexistent token");
        return metadataURI;
    }

    // ------------------------------------------------------------------
    // Owner powers — the complete list (see the contract header).
    // ------------------------------------------------------------------

    /// @notice Open or close the mint window. Owner power #1 of 3.
    function setMintOpen(bool open_) external onlyOwner {
        mintOpen = open_;
        emit MintWindowChanged(open_);
    }

    /// @notice Lower the supply cap. Owner power #2 of 3.
    /// @dev Can NEVER raise the cap, and can never set it below the number
    ///      already minted. Lowering it to exactly `totalMinted` closes
    ///      the drop by supply.
    function setMaxSupply(uint256 newMaxSupply) external onlyOwner {
        if (newMaxSupply > maxSupply || newMaxSupply < totalMinted) {
            revert InvalidMaxSupply(newMaxSupply);
        }
        emit MaxSupplyChanged(maxSupply, newMaxSupply);
        maxSupply = newMaxSupply;
    }

    // Owner power #3 of 3 — transferOwnership / renounceOwnership —
    // is inherited from OwnableMinimal, unmodified.

    // Deliberately absent: no payable functions, no receive/fallback (plain
    // BNB transfers to this contract revert), no withdraw, no owner mint,
    // no transfer restrictions, no fee switches. The badge promises
    // nothing of value — it is a commemorative proof that the holder's
    // Agent ID passed the gate.
}

contracts/ERC721Minimal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ERC721Minimal — a small, self-contained ERC-721 implementation
/// @notice AgentGate ships with zero external dependencies so that the
///         verified source on BscScan is exactly what you read here — no
///         library indirection to audit. This is a plain, complete ERC-721
///         (with the metadata extension) in one file: standard transfers,
///         approvals and safe-mint receiver checks. It deliberately has NO
///         transfer hooks, NO fees, NO pausing and NO blocking of any kind.
abstract contract ERC721Minimal {
    string public name;
    string public symbol;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
    }

    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {
        return
            interfaceId == 0x01ffc9a7 || // ERC165
            interfaceId == 0x80ac58cd || // ERC721
            interfaceId == 0x5b5e139f; // ERC721Metadata
    }

    function balanceOf(address owner) public view returns (uint256) {
        require(owner != address(0), "ERC721: zero address");
        return _balances[owner];
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner = _owners[tokenId];
        require(owner != address(0), "ERC721: nonexistent token");
        return owner;
    }

    function tokenURI(uint256 tokenId) public view virtual returns (string memory);

    function approve(address to, uint256 tokenId) public {
        address owner = ownerOf(tokenId);
        require(to != owner, "ERC721: approve to owner");
        require(
            msg.sender == owner || isApprovedForAll(owner, msg.sender),
            "ERC721: not authorized"
        );
        _tokenApprovals[tokenId] = to;
        emit Approval(owner, to, tokenId);
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        require(_owners[tokenId] != address(0), "ERC721: nonexistent token");
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) public {
        require(operator != msg.sender, "ERC721: approve to caller");
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address owner, address operator) public view returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        require(_isAuthorized(msg.sender, tokenId), "ERC721: not authorized");
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) public {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(
        address from,
        address to,
        uint256 tokenId,
        bytes memory data
    ) public {
        require(_isAuthorized(msg.sender, tokenId), "ERC721: not authorized");
        _transfer(from, to, tokenId);
        require(_checkOnERC721Received(from, to, tokenId, data), "ERC721: unsafe recipient");
    }

    function _isAuthorized(address spender, uint256 tokenId) internal view returns (bool) {
        address owner = ownerOf(tokenId);
        return (spender == owner ||
            isApprovedForAll(owner, spender) ||
            getApproved(tokenId) == spender);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        require(ownerOf(tokenId) == from, "ERC721: wrong from");
        require(to != address(0), "ERC721: zero address");
        delete _tokenApprovals[tokenId];
        _balances[from] -= 1;
        _balances[to] += 1;
        _owners[tokenId] = to;
        emit Transfer(from, to, tokenId);
    }

    function _safeMint(address to, uint256 tokenId) internal {
        _mint(to, tokenId);
        require(
            _checkOnERC721Received(address(0), to, tokenId, ""),
            "ERC721: unsafe recipient"
        );
    }

    function _mint(address to, uint256 tokenId) internal {
        require(to != address(0), "ERC721: zero address");
        require(_owners[tokenId] == address(0), "ERC721: already minted");
        _balances[to] += 1;
        _owners[tokenId] = to;
        emit Transfer(address(0), to, tokenId);
    }

    function _checkOnERC721Received(
        address from,
        address to,
        uint256 tokenId,
        bytes memory data
    ) private returns (bool) {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (
                bytes4 retval
            ) {
                return retval == IERC721Receiver.onERC721Received.selector;
            } catch {
                return false;
            }
        }
        return true;
    }
}

/// @notice Minimal receiver interface used by the safe-mint check above.
interface IERC721Receiver {
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external returns (bytes4);
}

/// @title OwnableMinimal — the smallest honest ownership implementation
/// @notice Single owner, transferable, renounceable. Nothing else. The full
///         extent of what the owner can do is defined by the contracts that
///         use this — for AgentGateBadge that list is short, enumerable and
///         disclosed in the README.
abstract contract OwnableMinimal {
    address public owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error NotOwner(address caller);

    constructor() {
        owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner(msg.sender);
        _;
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: zero address");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    /// @notice Give up ownership permanently. After this call every
    ///         owner-only function is frozen forever — for AgentGateBadge
    ///         that means the mint window and supply cap can never change
    ///         again.
    function renounceOwnership() public onlyOwner {
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }
}

contracts/IAgentID.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IAgentID — minimal interface for the SPACE ID Agent ID contract
/// @notice The Agent ID contract lives on BNB Smart Chain (chain id 56) at
///         0x60b9262456de011f7d15a54cdd8c48baaa8b022f. It is an ERC-721
///         ("SPACE ID Agent ID", symbol "AI") whose tokens are
///         non-transferable identity credentials: one verified (KYC) person
///         can hold exactly one Agent ID, shaped like `name.ai`.
///
///         AgentGate only ever needs one question answered — "does this
///         address hold an Agent ID?" — so this interface intentionally
///         exposes nothing but `balanceOf`. Keeping the surface this small
///         means any contract that integrates AgentGate takes on no extra
///         trust assumptions about the identity contract.
interface IAgentID {
    /// @notice Number of Agent ID tokens held by `account`.
    /// @dev Because an Agent ID is one-per-person and non-transferable,
    ///      `balanceOf(account) > 0` is a reliable "is a verified unique
    ///      human agent" check — the entire foundation of AgentGate.
    /// @param account The address to check.
    /// @return The number of Agent IDs held (0 or 1 in practice).
    function balanceOf(address account) external view returns (uint256);
}

contracts/MockAgentID.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IAgentID} from "./IAgentID.sol";

/// @title MockAgentID — test-only stand-in for the SPACE ID Agent ID contract
/// @notice Reproduces the one behaviour AgentGate depends on — `balanceOf`
///         returning 1 for registered holders, 0 for everyone else — so the
///         test suite can run entirely on a local chain. NOT for deployment:
///         unlike the real Agent ID, registration here is permissionless.
/// @dev Lives in contracts/ only so Hardhat compiles it with everything
///      else; it is never part of the production deployment.
contract MockAgentID is IAgentID {
    mapping(address => bool) private _holders;

    /// @notice Test helper: mark `account` as an Agent ID holder.
    function register(address account) external {
        _holders[account] = true;
    }

    /// @notice Test helper: remove holder status from `account`.
    function unregister(address account) external {
        _holders[account] = false;
    }

    function balanceOf(address account) external view override returns (uint256) {
        return _holders[account] ? 1 : 0;
    }
}
